/* ---------- the models as the demo uses them ---------- */

export type Size = { us: string; eu: string; /** how often this size sells, relative */ w: number; /** Picqer's product code */ code: string };
export type Model = {
  name: string;
  /** the name as it comes through from Alias (GOAT) */
  alias: string;
  style: string;
  color: string;
  run: Run;
  hype: number;
  /** release day (UTC ms) */
  rel: number;
  /** typical resale price in €, for the most asked sizes */
  eur: number;
  shape: Shape;
  sizes: Size[];
  /** what a search looks in (lower case) */
  hay: string;
};

/** How an Alias (GOAT) product name reads once its URL slug is made readable, e.g. "Air Jordan 4 Retro Bred
 * Reimagined", "Dunk Low Retro White Black Panda", "Wmns Air Jordan 4 Retro Frozen Moments", "Adidas Samba Og …"
 * (Nike's own models come without "Nike"). */
export function aliasName(name: string): string {
  let n = name.replace(/^Jordan /, "Air Jordan ").replace(/^Nike /, "").replace(/\s*\(GS\)$/, " GS");
  if (/\(Women's\)$/.test(n)) n = `Wmns ${n.replace(/\s*\(Women's\)$/, "")}`;
  return n.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean).map((w) => (w === "x" ? w : w[0].toUpperCase() + w.slice(1))).join(" ");
}

export function shapeOf(name: string): Shape {
  if (/Slide|Mind 001/.test(name)) return "slide";
  if (/Jordan 1 Retro High|Dunk High/.test(name)) return "high";
  if (/Jordan (3|4|5|6|11|12) Retro(?! Low)/.test(name)) return "mid";
  if (/Air Max|Vomero|Shox|Mind 002|New Balance (990|2002R|9060|1906|530|1000|204L|740)|ASICS (Gel|GT)|Salomon/.test(name)) return "runner";
  return "low";
}

// the usual resale price of a kind (€), before how well the model sells
const PRICE: [RegExp, number][] = [
  [/Jordan 1 Retro High/, 185], [/Jordan 1 Retro Low/, 140], [/Jordan 3 /, 190], [/Jordan 4 /, 225], [/Jordan 5 /, 200], [/Jordan 6 /, 195],
  [/Jordan 11 Retro Low/, 170], [/Jordan 11 /, 225], [/Jordan 12 /, 190], [/SB Dunk/, 170], [/Dunk High/, 130], [/Dunk/, 115], [/Air Force 1/, 110],
  [/Air Max 1 /, 150], [/Air Max 90/, 140], [/Air Max 95/, 180], [/Air Max Plus/, 170], [/Air Max Dn/, 160], [/Vomero/, 155], [/Kobe/, 260],
  [/990v/, 215], [/2002R/, 150], [/9060/, 160], [/1906/, 150], [/550/, 115], [/530/, 100], [/New Balance/, 140],
  [/Samba|Gazelle|Campus|Handball|SL 72|Tokyo/, 105], [/ASICS/, 135], [/Salomon/, 175],
];

const ofKind = (name: string) => PRICE.find(([re]) => re.test(name))?.[1] ?? 140;

/** What one size of a model resells for (€): the model's price, a little more at the ends of the run. */
export function priceOf(m: Model, si: number): number {
  const edge = Math.abs(si - (m.sizes.length - 1) / 2) / Math.max(1, m.sizes.length / 2);
  return Math.round(m.eur * (1 + 0.12 * edge * edge));
}

export const MODELS: Model[] = ROWS.map(([name, style, color, run, hype, rel, eur]) => {
  const r = RUNS[run];
  const kids = run === "gs" ? 0.72 : run === "w" ? 0.92 : 1;
  return {
    name, alias: aliasName(name), style, color, run, hype, rel: Date.parse(`${rel}T00:00:00Z`),
    eur: eur ?? Math.round((ofKind(name) * (0.82 + 0.09 * hype) * kids) / 5) * 5,
    shape: shapeOf(name),
    sizes: r.sizes.map(([us, eu]) => {
      const z = (Number.parseFloat(us) - r.peak) / r.spread;
      // rounded: Math.exp may differ in its last digit between browsers, and every visitor must draw the same rows.
      // Picqer's product code is the style code and the EU size ("DD1391-100-42", "B75806-42 2/3")
      return { us, eu, w: Math.round(Math.exp(-z * z) * 1e6) / 1e6 + 0.06, code: `${style}-${eu}` };
    }),
    hay: `${name}\n${aliasName(name)}\n${style}\n${style.replace(/-/g, " ")}`.toLowerCase(),
  };
});
